	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsvRef.html#SetCellByName
	 * @param int $rowIndex
	 * @param ?string $columnName
	 * @param ?string $contentStr
	 * @return bool
	 */
	function SetCellByName($rowIndex,$columnName,$contentStr) {
		return CkCsv_SetCellByName($this->_cPtr,$rowIndex,$columnName,$contentStr);
	}

	/**
	 * Sets the name of the column at zero-based index ARG1 to ARG2. The first column   is at index 0.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsvRef.html#SetColumnName
	 * @param int $index
	 * @param ?string $columnName
	 * @return bool
	 */
	function SetColumnName($index,$columnName) {
		return CkCsv_SetColumnName($this->_cPtr,$index,$columnName);
	}

	/**
	 * Sorts the data rows using the values in the column named by ARG1. The   column-name row is not moved.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsvRef.html#SortByColumn
	 * @param ?string $columnName
	 * @param bool $ascending
	 * @param bool $caseSensitive
	 * @return bool
	 */
	function SortByColumn($columnName,$ascending,$caseSensitive) {
		return CkCsv_SortByColumn($this->_cPtr,$columnName,$ascending,$caseSensitive);
	}

	/**
	 * Sorts the data rows using the values in the column at zero-based index ARG1.   The column-name row, when present, is not moved.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsvRef.html#SortByColumnIndex
	 * @param int $index
	 * @param bool $ascending
	 * @param bool $caseSensitive
	 * @return bool
	 */
	function SortByColumnIndex($index,$ascending,$caseSensitive) {
		return CkCsv_SortByColumnIndex($this->_cPtr,$index,$ascending,$caseSensitive);
	}

	/**
	 * Gets the worksheet names contained in an Excel .xlsx workbook.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsvRef.html#XlsxGetSheets
	 * @param CkZip $xlsx
	 * @param CkStringTable $sheetNames
	 * @return bool
	 */
	function XlsxGetSheets($xlsx,$sheetNames) {
		return CkCsv_XlsxGetSheets($this->_cPtr,$xlsx,$sheetNames);
	}

	/**
	 * Loads a worksheet from an Excel .xlsx workbook into this CSV object.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsvRef.html#XlsxLoadSheet
	 * @param CkZip $zip
	 * @param ?string $sheetName
	 * @return bool
	 */
	function XlsxLoadSheet($zip,$sheetName) {
		return CkCsv_XlsxLoadSheet($this->_cPtr,$zip,$sheetName);
	}
}
